<script setup lang="ts">
import RecordIdentifier from './RecordIdentifier.vue'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Pencil, Trash2, Send, Search, RotateCcw } from 'lucide-vue-next'
import RichEditor from './RichEditor.vue'
import { request, send } from './api'
import { variables, presets, sampleValues, placeholders, substitute, plainDoc } from '../../shared/messages'
type Mode='templates'|'messages'; const props=defineProps<{mode:Mode}>()
const templates=ref<any[]>([]),messages=ref<any[]>([]),exams=ref<any[]>([]),step=ref(1),tab=ref('normal'),page=ref(1),loading=ref(false),loadError=ref('')
const imageBusy=ref(false)
const templateOpen=ref(false),wizardOpen=ref(false),confirmOpen=ref(false),previewText=ref('')
const templateEditor=ref<any>(),messageEditor=ref<any>(),templateWildcard=ref(''),messageWildcard=ref('')
const filters=reactive({name:'',title:'',status:'',sendType:''}),applied=reactive({...filters})
const templateStatuses:Record<string,string>={draft:'草稿',published:'已发布',offline:'已下架'}
const messageStatuses:Record<string,string>={draft:'暂存',scheduled:'待发送',active:'执行中',sent:'已发送',cancelled:'已取消'}
const statusTone=(value:string)=>['published','sent','active'].includes(value)?'success':value==='scheduled'?'warning':'info'
const examNames=(ids:string[])=>ids?.length?ids.map(id=>exams.value.find(e=>e.id===id)?.name||'考试已不存在').join('、'):'全部考试'
const permissionNames=(ids:string[])=>ids?.length?ids.map(id=>permissions.find(p=>p.id===id)?.name||id).join('、'):'—'
const channelNames=(ids:string[])=>ids?.map(id=>({h5:'H5',miniapp:'小程序',app:'APP'}[id]||id)).join('、')||'—'
const form=reactive<any>({id:'',name:'',status:'draft',title:'',content:'',document:plainDoc(''),variables:[]})
const draft=reactive<any>({id:'',sendType:'manual',status:'draft',title:'',content:'',document:plainDoc(''),templateId:null,systemKey:'',channels:['h5'],categoryIds:[],examIds:[],permissionLevels:[],schedule:{}})
const permissions=[{id:'free',name:'普通会员'},{id:'vip',name:'VIP'},{id:'svip',name:'SVIP'}], l1=[{id:'social-work',name:'社会工作'}]
const filteredRows=computed(()=>props.mode==='templates'?templates.value.filter(r=>(!applied.name||r.name.includes(applied.name))&&(!applied.title||r.title.includes(applied.title))&&(!applied.status||r.status===applied.status)):tab.value==='system'?presets.filter(r=>(!applied.name||r.name.includes(applied.name))&&(!applied.title||r.title.includes(applied.title))):messages.value.filter(r=>(!applied.title||r.title.includes(applied.title))&&(!applied.sendType||r.send_type===applied.sendType)&&(!applied.status||r.status===applied.status)))
const pageRows=computed(()=>filteredRows.value.slice((page.value-1)*20,page.value*20))
function search(){Object.assign(applied,Object.fromEntries(Object.entries(filters).map(([key,value])=>[key,value.trim()])));page.value=1}
function reset(){Object.assign(filters,{name:'',title:'',status:'',sendType:''});search()}
watch(tab,reset)
watch(()=>filteredRows.value.length,total=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(total/20)))})
function text(n:any):string{return !n?'':typeof n.text==='string'?n.text:Array.isArray(n.content)?n.content.map(text).join(''):''}
async function load(){loading.value=true;loadError.value='';try{const [t,m,e]=await Promise.all([request('/admin/message-templates'),request('/admin/messages'),request('/exams')]);templates.value=t;messages.value=m;exams.value=e}catch(e:any){loadError.value=e.message}finally{loading.value=false}};onMounted(load)
function newTemplate(){Object.assign(form,{id:crypto.randomUUID(),name:'',status:'draft',title:'',content:'',document:plainDoc(''),variables:[]});templateOpen.value=true}
function editTemplate(r:any){Object.assign(form,{...r,document:r.document||plainDoc(r.content||'')});templateOpen.value=true}
async function saveTemplate(){if(imageBusy.value)return ElMessage.warning('图片正在上传，请稍候');if(!form.name.trim()||!form.title.trim()||!form.content.trim())return ElMessage.warning('请填写模板名称、消息标题和正文');form.variables=placeholders(form.title+'\n'+form.content);await send('/admin/message-templates/'+form.id,form,'PUT');templateOpen.value=false;ElMessage.success('消息模板已保存');load()}
function insert(kind:string){const v=kind.startsWith('template')?templateWildcard.value:messageWildcard.value;if(!v)return;if(kind==='templateTitle')form.title+=v;if(kind==='messageTitle')draft.title+=v;if(kind==='templateBody')templateEditor.value?.insertText(v);if(kind==='messageBody')messageEditor.value?.insertText(v);if(kind.startsWith('template'))templateWildcard.value='';else messageWildcard.value=''}
function applyTemplate(t:any){if(!t)return;draft.templateId=t.id;draft.title=t.title;draft.content=t.content||'';draft.document=t.document||plainDoc(t.content||'')}
function applyPreset(p:any){draft.systemKey=p.key;draft.title=p.title;draft.content=p.body;draft.document=plainDoc(p.body)}
function newMessage(){Object.assign(draft,{id:crypto.randomUUID(),sendType:'manual',status:'draft',title:'',content:'',document:plainDoc(''),templateId:null,systemKey:'',channels:['h5'],categoryIds:[],examIds:[],permissionLevels:[],schedule:{frequency:'weekly',weekday:1,time:'09:00'}});step.value=1;wizardOpen.value=true}
function editMessage(r:any){Object.assign(draft,{...r,permissionLevels:r.permission_levels||[],examIds:r.exam_ids||[],categoryIds:r.category_ids||[],schedule:r.schedule||{}});step.value=2;wizardOpen.value=true}
function editSystem(p:any){newMessage();draft.systemKey=p.key;draft.sendType='scheduled';applyPreset(p);step.value=2}
function next(){if(imageBusy.value)return ElMessage.warning('图片正在上传，请稍候');if(step.value===1){step.value=2;return}if(step.value===2){if(!draft.permissionLevels.length)return ElMessage.warning('请选择会员权限');if(!draft.title.trim()||!draft.content.trim())return ElMessage.warning('请填写消息标题和正文');previewText.value=substitute(draft.title+'\n\n'+draft.content,sampleValues);step.value=3}}
async function saveDraft(){if(imageBusy.value)return ElMessage.warning('图片正在上传，请稍候');await send('/admin/messages',draft,'POST');wizardOpen.value=false;ElMessage.success('消息已暂存');load()}
async function finalSend(){if(imageBusy.value)return ElMessage.warning('图片正在上传，请稍候');await ElMessageBox.confirm(draft.sendType==='scheduled'?'确认执行这个发送计划吗？':'确认立即发送这条消息吗？','最终确认',{type:'warning',confirmButtonText:draft.sendType==='scheduled'?'定时发送':'立即发送',cancelButtonText:'返回'});await send('/admin/messages',draft,'POST');if(draft.sendType==='manual'&&!draft.schedule?.enabled)await send('/admin/messages/'+draft.id+'/send',{});wizardOpen.value=false;ElMessage.success('操作成功');load()}
async function remove(r:any){try{await ElMessageBox.confirm('删除后无法恢复，确定删除吗？','严重操作确认',{type:'warning'});await send('/admin/messages/'+r.id,{},'DELETE');load()}catch{}}
async function sendRow(r:any){try{await ElMessageBox.confirm('确认立即发送这条消息吗？','发送确认',{type:'warning',confirmButtonText:'立即发送'});await send('/admin/messages/'+r.id+'/send',{force:true});load()}catch{}}
function fmt(v:any){return v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'}
function sendTypeLabel(v:string){return ({manual:'手动发送',scheduled:'计划发送',preset:'系统预置',draft:'暂存'} as Record<string,string>)[v]||'—'}
defineExpose({load,newItem:()=>props.mode==='templates'?newTemplate():newMessage(),openReference:(row:any)=>props.mode==='templates'?editTemplate(row):editMessage(row)})
</script>
<template>
<section class="messages-page">
 <el-tabs v-if="props.mode==='messages'" v-model="tab" class="message-tabs"><el-tab-pane label="普通消息" name="normal"/><el-tab-pane label="系统消息" name="system"/></el-tabs>
 <form class="admin-filters" @submit.prevent="search">
  <label v-if="props.mode==='templates'||tab==='system'" class="admin-filter-field"><span>{{props.mode==='templates'?'模板名称':'消息名称'}}</span><el-input v-model="filters.name" :placeholder="props.mode==='templates'?'搜索模板名称':'搜索消息名称'" aria-label="名称" clearable/></label>
  <label class="admin-filter-field"><span>消息标题</span><el-input v-model="filters.title" placeholder="搜索消息标题" aria-label="消息标题" clearable/></label>
  <label v-if="props.mode==='messages'&&tab==='normal'" class="admin-filter-field"><span>发送类型</span><el-select v-model="filters.sendType" :empty-values="[null,undefined]" aria-label="发送类型"><el-option label="全部类型" value=""/><el-option label="手动发送" value="manual"/><el-option label="计划发送" value="scheduled"/><el-option label="系统预置" value="preset"/><el-option label="暂存" value="draft"/></el-select></label>
  <label v-if="props.mode==='templates'||tab==='normal'" class="admin-filter-field"><span>状态</span><el-select v-model="filters.status" :empty-values="[null,undefined]" aria-label="状态"><el-option label="全部状态" value=""/><el-option v-for="(label,value) in props.mode==='templates'?templateStatuses:messageStatuses" :key="value" :label="label" :value="value"/></el-select></label>
  <div class="admin-filter-actions"><el-button type="primary" native-type="submit"><Search :size="16"/>查询</el-button><el-button @click="reset"><RotateCcw :size="16"/>重置</el-button></div>
 </form>
 <el-alert v-if="loadError" :title="loadError" type="error" :closable="false" show-icon/>
 <div class="table-toolbar"><span>{{props.mode==='templates'?'消息模板':tab==='normal'?'普通消息':'系统消息'}} <b>{{filteredRows.length}}</b></span></div>
 <el-table v-if="props.mode==='templates'" :key="'templates'" v-loading="loading" :data="pageRows" row-key="id">
  <template #empty><el-empty description="当前条件下暂无消息模板" :image-size="80"/></template>
  <el-table-column prop="name" label="模板名称" min-width="200" show-overflow-tooltip/>
  <el-table-column prop="title" label="消息标题" min-width="300" show-overflow-tooltip/>
  <el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="statusTone(row.status)">{{templateStatuses[row.status]||'未知状态'}}</el-tag></template></el-table-column>
  <el-table-column label="操作" width="80" fixed="right"><template #default="{row}"><div class="row-actions"><el-tooltip content="编辑"><el-button link type="primary" aria-label="编辑消息模板" @click="editTemplate(row)"><Pencil :size="17"/></el-button></el-tooltip></div></template></el-table-column>
 </el-table>
 <el-table v-else-if="tab==='normal'" :key="'messages'" v-loading="loading" :data="pageRows" row-key="id">
  <template #empty><el-empty description="当前条件下暂无消息" :image-size="80"/></template>
  <el-table-column prop="title" label="消息标题" min-width="260" show-overflow-tooltip/>
  <el-table-column label="展示端" width="110"><template #default="{row}">{{channelNames(row.channels)}}</template></el-table-column>
  <el-table-column label="考试项目" min-width="200" show-overflow-tooltip><template #default="{row}">{{examNames(row.exam_ids)}}</template></el-table-column>
  <el-table-column label="会员权限" min-width="170" show-overflow-tooltip><template #default="{row}">{{permissionNames(row.permission_levels)}}</template></el-table-column>
  <el-table-column label="发送类型" width="115"><template #default="{row}">{{sendTypeLabel(row.send_type)}}</template></el-table-column>
  <el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="statusTone(row.status)">{{messageStatuses[row.status]||'未知状态'}}</el-tag></template></el-table-column>
  <el-table-column label="发布时间" width="180"><template #default="{row}">{{fmt(row.sent_at)}}</template></el-table-column>
  <el-table-column label="操作" width="138" fixed="right"><template #default="{row}"><div class="row-actions"><el-tooltip content="编辑"><el-button link type="primary" aria-label="编辑消息" @click="editMessage(row)"><Pencil :size="17"/></el-button></el-tooltip><el-tooltip content="删除"><el-button link type="danger" aria-label="删除消息" @click="remove(row)"><Trash2 :size="17"/></el-button></el-tooltip><el-tooltip v-if="row.status!=='active'" content="发送"><el-button link type="primary" aria-label="发送消息" @click="sendRow(row)"><Send :size="17"/></el-button></el-tooltip></div></template></el-table-column>
 </el-table>
 <el-table v-else :key="'system'" :data="pageRows" row-key="key">
  <template #empty><el-empty description="当前条件下暂无系统消息" :image-size="80"/></template>
  <el-table-column prop="name" label="消息名称" min-width="180" show-overflow-tooltip/><el-table-column prop="help" label="触发说明" min-width="280" show-overflow-tooltip/><el-table-column prop="title" label="默认标题" min-width="260" show-overflow-tooltip/>
  <el-table-column label="操作" width="80" fixed="right"><template #default="{row}"><div class="row-actions"><el-tooltip content="编辑内容"><el-button link type="primary" aria-label="编辑系统消息" @click="editSystem(row)"><Pencil :size="17"/></el-button></el-tooltip></div></template></el-table-column>
 </el-table>
 <div class="pagination"><span>共 {{filteredRows.length}} 条</span><el-pagination v-model:current-page="page" :page-size="20" :total="filteredRows.length" layout="prev,pager,next"/></div>
</section>
<el-drawer :close-on-click-modal="false" v-model="templateOpen" title="编辑消息模板" direction="rtl" size="720px"><RecordIdentifier :id="form.id" table="message_templates"/><el-form label-position="top"><el-form-item label="模板名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="发布状态"><el-select v-model="form.status"><el-option label="草稿" value="draft"/><el-option label="已发布" value="published"/><el-option label="已下架" value="offline"/></el-select></el-form-item><el-form-item label="消息标题" required><div class="var-row title-row"><el-input v-model="form.title"/><el-select v-model="templateWildcard" placeholder="选择通配符" clearable><el-option v-for="v in variables" :key="v.key" :label="v.label" :value="'{{'+v.key+'}}'"/></el-select><el-button @click="insert('templateTitle')">插入到标题</el-button></div></el-form-item><el-form-item label="正文" required><div class="var-row"><el-select v-model="templateWildcard" placeholder="选择通配符" clearable><el-option v-for="v in variables" :key="v.key" :label="v.label" :value="'{{'+v.key+'}}'"/></el-select><el-button @click="insert('templateBody')">插入到正文</el-button></div><RichEditor ref="templateEditor" :model-value="form.document" :plain-text="form.content" :content-id="form.id" :allow-media="false" :allow-handouts="false" @busy="imageBusy=$event" @update:model-value="(d:any)=>{form.document=d;form.content=text(d).trim()}"/></el-form-item></el-form><template #footer><el-button @click="templateOpen=false">取消</el-button><el-button type="primary" :disabled="imageBusy" @click="saveTemplate">保存模板</el-button></template></el-drawer>
<el-drawer :close-on-click-modal="false" v-model="wizardOpen" :title="step===1?'新建消息':draft.systemKey?'编辑系统消息':draft.sendType==='scheduled'?'编辑计划消息':'编辑手动消息'" direction="rtl" size="820px"><RecordIdentifier :id="draft.id" table="messages"/><div class="wizard-step"><span :class="{active:step===1}">1 选择发送方式</span><i></i><span :class="{active:step===2}">2 编辑内容与范围</span><i></i><span :class="{active:step===3}">3 预览确认</span></div><template v-if="step===1"><div class="send-choice"><button :class="{selected:draft.sendType==='manual'}" @click="draft.sendType='manual'"><strong>手动发送</strong><span>运营公告、活动通知</span></button><button :class="{selected:draft.sendType==='scheduled'}" @click="draft.sendType='scheduled'"><strong>计划发送</strong><span>按周期自动发送</span></button></div></template><template v-else-if="step===2"><el-form label-position="top"><el-form-item label="展示端"><el-checkbox-group v-model="draft.channels"><el-checkbox label="h5">H5</el-checkbox><el-checkbox label="miniapp" disabled>小程序</el-checkbox><el-checkbox label="app" disabled>APP</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="消息标题" required><div class="var-row title-row"><el-input v-model="draft.title"/><el-select v-model="messageWildcard" placeholder="选择通配符" clearable><el-option v-for="v in variables" :key="v.key" :label="v.label" :value="'{{'+v.key+'}}'"/></el-select><el-button @click="insert('messageTitle')">插入到标题</el-button></div></el-form-item><div class="scope-row"><el-form-item label="考试项目分类"><el-select v-model="draft.categoryIds" multiple collapse-tags placeholder="全部分类" @change="v=>{if(!v.length)draft.examIds=[]}"><el-option v-for="c in l1" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="考试项目"><el-select v-model="draft.examIds" multiple collapse-tags placeholder="全部考试" :disabled="!draft.categoryIds.length"><el-option v-for="e in exams" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item></div><el-form-item label="会员权限（必选）"><el-checkbox-group v-model="draft.permissionLevels"><el-checkbox v-for="p in permissions" :key="p.id" :label="p.id">{{p.name}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="正文" required><div class="var-row"><el-select v-model="messageWildcard" placeholder="选择通配符" clearable><el-option v-for="v in variables" :key="v.key" :label="v.label" :value="'{{'+v.key+'}}'"/></el-select><el-button @click="insert('messageBody')">插入到正文</el-button></div><RichEditor ref="messageEditor" :model-value="draft.document" :plain-text="draft.content" :content-id="draft.id" :allow-media="false" :allow-handouts="false" @busy="imageBusy=$event" @update:model-value="(d:any)=>{draft.document=d;draft.content=text(d).trim()}"/></el-form-item><el-form-item label="选择消息模板（可选）"><el-select clearable placeholder="不使用模板" @change="(id:string)=>applyTemplate(templates.find(t=>t.id===id))"><el-option v-for="t in templates" :key="t.id" :label="t.name" :value="t.id"/></el-select></el-form-item><el-form-item v-if="draft.sendType==='manual'" label="定时发送"><div class="schedule-row"><el-switch v-model="draft.schedule.enabled"/><el-date-picker v-if="draft.schedule.enabled" v-model="draft.schedule.scheduledAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></div></el-form-item></el-form></template><template v-else><div class="preview-pane"><span class="preview-label">H5 用户端预览</span><h2>{{previewText.split('\n\n')[0]}}</h2><p>{{previewText.split('\n\n').slice(1).join('\n\n')}}</p><small>通配符已使用示例数据替换</small></div></template><template #footer><el-button @click="wizardOpen=false">取消</el-button><el-button v-if="step>1" @click="step--">上一步</el-button><el-button v-if="step===2" :disabled="imageBusy" @click="saveDraft">暂存</el-button><el-button v-if="step===2" :disabled="imageBusy" @click="next">下一步</el-button><el-button v-if="step===1" type="primary" :disabled="imageBusy" @click="next">下一步</el-button><el-button v-if="step===3" :disabled="imageBusy" @click="saveDraft">暂存</el-button><el-button v-if="step===3" type="primary" :disabled="imageBusy" @click="finalSend">{{draft.sendType==='scheduled'?'定时发送':'立即发送'}}</el-button></template></el-drawer>
</template>
<style scoped>.messages-page{min-width:0}.table-toolbar b{margin-left:6px;color:var(--el-text-color-regular)}.row-actions{flex-wrap:nowrap}.var-row{display:flex;gap:8px}.var-row .el-input{flex:1}.var-row .el-select{width:230px}.scope-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.schedule-row{display:flex;align-items:center;gap:24px}.send-choice{display:grid;grid-template-columns:1fr 1fr;gap:14px}.send-choice button{padding:20px;text-align:left;background:#fff;border:1px solid #d9e3ef;border-radius:10px}.send-choice button.selected{border-color:#3569e8;background:#f3f7ff}.wizard-step{display:flex;gap:12px;margin-bottom:22px}.wizard-step .active{color:#3569e8;font-weight:700}.preview-pane{padding:24px;border:1px solid #dfe8f2;border-radius:12px;background:#f7faff}.preview-pane h2{margin:16px 0 10px;color:#203957}.preview-pane p{white-space:pre-line;line-height:1.8;color:#526a84}.preview-pane small{color:#98a6b5}.message-tabs :deep(.el-tabs__nav-wrap:after){background:#e8edf3}.message-tabs :deep(.el-tabs__item){height:42px;padding:0 22px;font-weight:600}.message-tabs :deep(.el-tabs__active-bar){height:3px;border-radius:3px}@media(max-width:900px){.scope-row{grid-template-columns:1fr}.var-row{flex-wrap:wrap}.var-row .el-select{width:100%}}</style>
